mapper.select:
SELECT IF(COUNT(user_id) > 0, 1, 0) AS `exists`
FROM users
WHERE login_id = #{loginId}

SELECT IF(COUNT(user_id) > 0, 1, 0) AS `exists`
FROM users
WHERE email = #{email}

SELECT login_id, 1 AS `exists`
FROM users
WHERE name = #{name}
  AND email = #{email}
LIMIT 1

SELECT user_id, login_id, name, email, 1 AS `exists`
FROM users
WHERE login_id = #{loginId}
  AND email = #{email}
LIMIT 1

mapper.update:
UPDATE users
SET password = #{password},
    salt = #{salt}
WHERE login_id = #{loginId}
  AND email = #{email}

UPDATE users
birth_date = #{birthDate}, gender = #{gender}, height_cm = #{height}, weight_kg = #{weight},
-- 성향 4축은 항상 함께 저장된다 trait_companion = #{companion}, trait_competition = #{competition}, trait_place = #{place}, trait_intensity = #{intensity}
WHERE user_id = #{userId}
